const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis(process.env.REDIS_URL);
const redisStore = new RedisStore({ client: redisClient });

app.use(session({
  store: redisStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.get('/api/users/:targetUserId/active-sessions', (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Users can only view their own sessions unless they are compliance admins within the same org
  const isSelf = req.session.userId === req.params.targetUserId;
  const isOrgAdmin = req.session.role === 'ORG_ADMIN';

  if (!isSelf && !isOrgAdmin) {
    return res.status(403).json({ error: 'Access denied: cannot view other users\' sessions' });
  }

  redisStore.all((err, sessions) => {
    if (err) {
      return res.status(500).json({ error: 'Failed to scan session store' });
    }

    const matchedSessions = [];
    for (const [sid, sess] of Object.entries(sessions || {})) {
      if (sess.userId === req.params.targetUserId) {
        // Org admins can only see users within their organization
        if (isOrgAdmin && sess.organizationId !== req.session.organizationId) {
          continue;
        }

        matchedSessions.push({
          // Mask session ID token to prevent session hijacking
          sessionIdMasked: sid.slice(0, 6) + '...' + sid.slice(-4),
          ip: sess.ipAddress,
          userAgent: sess.userAgent,
          lastActivity: sess.lastActivity
        });
      }
    }

    res.json({
      targetUserId: req.params.targetUserId,
      sessions: matchedSessions
    });
  });
});

app.listen(3033);
